let state={tenant:null,staff:[],admins:[],currentUserId:null,currentAdminLevel:'admin',currentRole:'staff',companyPermissions:[],communities:[],submissions:[],templates:[],globalTemplates:[],platformResources:[],companyResources:[]};
const JOB_CATEGORIES=['社區管理','會計','總務','人事','勤務','秘書','保全','機動','財務','其他'];
const JOB_LEVELS=['經理','副理','助理','一般'];
const STAFF_PERMISSIONS=[['todo','代辦事項'],['work-journal','工作日誌'],['finance','財務／會計'],['committee','管理委員會'],['residents','住戶名冊'],['vendors','廠商聯繫'],['handover','交接清冊'],['company-resources','公司資源'],['manage-staff','公司人員管理'],['manage-communities','社區管理'],['view-submissions','交接紀錄'],['manage-templates','公司文件／範本'],['schedule','班表']];
const COMPANY_PERMISSIONS=STAFF_PERMISSIONS.filter(x=>['finance','company-resources','manage-staff','manage-communities','view-submissions','manage-templates','schedule'].includes(x[0]));
const SITE_PERMISSIONS=STAFF_PERMISSIONS.filter(x=>['todo','work-journal','finance','committee','residents','vendors','handover','schedule'].includes(x[0]));
const DEFAULT_STAFF_PERMISSIONS=STAFF_PERMISSIONS.map(x=>x[0]);
async function loadPermissionCatalog(){
  const fallbackSite=SITE_PERMISSIONS.map(([id,label])=>({id,action:id,label,icon:'•',enabled:true}));
  try{
    const companyMenu=await api('/api/company/menu-config');
    let site=fallbackSite;
    try{const siteMenu=await api('/api/company/site-menu-config');if(Array.isArray(siteMenu.items)&&siteMenu.items.length)site=siteMenu.items;}catch(e){}
    return {company:Array.isArray(companyMenu.items)?companyMenu.items:[],site};
  }catch(e){
    return {company:[],site:fallbackSite};
  }
}
// 人事資料、薪資是敏感權限：另外顯示，只有公司管理員可以勾選
const SENSITIVE_PERMS=[['hr-records','👥 人事資料設定（人事管理：到職、特休、加保級距、薪轉帳號）'],['payroll','💰 薪資設定（人員薪資、薪資統計表、薪資單、借資、代扣款）']];
function sensitivePermHtml(selected,attr){const admin=state.currentRole==='company_admin';return `<div class="workspace-permission-group sensitive-perms"><div class="workspace-permission-title">🔒 人事／薪資權限${admin?'':'（只有公司管理員可以設定）'}</div><div class="check-list">${SENSITIVE_PERMS.map(([k,l])=>`<label class="check-row"><input type="checkbox" data-${attr}-perm="${k}" ${selected.has(k)?'checked':''} ${admin?'':'disabled'}> ${l}</label>`).join('')}</div></div>`;}
function permissionOptionsHtml(items, selected, attrName){
  const list=(items||[]).filter(x=>x&&x.enabled!==false&&String(x.action||'')!=='home');
  // 現場目錄（有 perm_key）：母目錄＋子項逐項勾選；子項沒勾的存成 nosub:<id>，沒有權限代碼的目錄沒勾存成 nomenu:<id>
  if(list.some(x=>'perm_key' in x)) return sitePermissionTreeHtml(list,selected,attrName);
  const seen=new Set(SENSITIVE_PERMS.map(x=>x[0]));
  return list.map(x=>{
    const key=menuPermissionKeyClient(x);
    if(!key || seen.has(key)) return '';
    seen.add(key);
    return `<label class="check-row"><input type="checkbox" data-${attrName}-perm="${escapeAttr(key)}" ${selected.has(key)?'checked':''}> ${escapeHtml(x.icon||'')} ${escapeHtml(x.label||'未命名')}</label>`;
  }).join('');
}
function sitePermissionTreeHtml(list,selected,attrName){
  const ids=new Set(list.map(x=>String(x.id)));const kids={};
  for(const x of list)if(x.parentId&&ids.has(String(x.parentId)))(kids[x.parentId] ||= []).push(x);
  const seen=new Set();
  return list.filter(x=>!x.parentId||!ids.has(String(x.parentId))).map(x=>{
    const key=x.perm_key||'';const node=key||('free:'+x.id);
    if(seen.has(node))return '';seen.add(node);
    const on=key?selected.has(key):!selected.has('nomenu:'+x.id);
    const parent=`<label class="check-row perm-parent"><input type="checkbox" data-perm-node="${escapeAttr(node)}" ${key?`data-${attrName}-perm="${escapeAttr(key)}"`:`data-free-id="${escapeAttr(x.id)}"`} ${on?'checked':''}> ${escapeHtml(x.icon||'')} ${escapeHtml(x.label||'未命名')}</label>`;
    const ch=kids[x.id]||[];
    if(!ch.length)return `<div class="perm-node">${parent}</div>`;
    return `<div class="perm-node has-subs">${parent}<div class="perm-subs">${ch.map(c=>`<label class="check-row perm-sub"><input type="checkbox" data-sub-of="${escapeAttr(node)}" data-sub-id="${escapeAttr(c.id)}" ${on&&!selected.has('nosub:'+c.id)?'checked':''}> ${escapeHtml(String(c.label||'未命名'))}</label>`).join('')}</div></div>`;
  }).join('');
}
// 勾母目錄＝子項全勾；子項全部取消＝母目錄取消
document.addEventListener('change',e=>{
  const t=e.target;if(!(t instanceof HTMLInputElement))return;
  const node=t.closest('.perm-node');if(!node)return;
  if(t.dataset.permNode){node.querySelectorAll('input[data-sub-of]').forEach(s=>s.checked=t.checked);}
  else if(t.dataset.subOf){const p=node.querySelector('input[data-perm-node]');if(p)p.checked=[...node.querySelectorAll('input[data-sub-of]')].some(s=>s.checked);}
});
// 依母目錄重設子項（換職位帶入預設權限時用）
function syncSubPerms(root,list=[]){const sel=new Set(list);root.querySelectorAll('.perm-node').forEach(n=>{const p=n.querySelector('input[data-perm-node]');if(!p)return;if(p.dataset.freeId)p.checked=!sel.has('nomenu:'+p.dataset.freeId);n.querySelectorAll('input[data-sub-of]').forEach(s=>s.checked=p.checked&&!sel.has('nosub:'+s.dataset.subId));});}
// 收集細項設定：把沒勾的子項／目錄轉成 nosub:／nomenu:
function withSubPerms(root,perms){
  const out=(perms||[]).filter(k=>!/^(nosub|nomenu):/.test(k));
  root.querySelectorAll('.perm-node').forEach(n=>{
    if(n.closest('[style*="display: none"],[style*="display:none"]'))return;
    const p=n.querySelector('input[data-perm-node]');if(!p)return;
    if(p.dataset.freeId&&!p.checked)out.push('nomenu:'+p.dataset.freeId);
    const subs=[...n.querySelectorAll('input[data-sub-of]')];
    if(p.checked&&subs.some(s=>!s.checked))subs.filter(s=>!s.checked).forEach(s=>out.push('nosub:'+s.dataset.subId));
  });
  return [...new Set(out)];
}

function menuPermissionKeyClient(item){
  const raw=`${item?.id||''} ${item?.action||''} ${item?.label||''}`.toLowerCase();
  const rules=[
    ['hr-records',['hr-records','人事管理','人事資料']],['payroll',['payroll','薪資','借資','借支']],
    ['manage-staff',['staff','人員管理','公司人員','人員','人事']],['manage-communities',['communities','社區管理']],['view-submissions',['submissions','交接紀錄','交接清冊紀錄']],['manage-templates',['templates','公司文件','制式文件','範本']],['schedule',['schedule','班表']],
    ['todo',['todo','代辦事項']],['work-journal',['work-journal','工作日誌']],['finance',['finance','財務','會計']],['committee',['committee','管理委員會']],['residents',['residents','住戶名冊']],['vendors',['vendors','廠商聯繫']],['handover',['handover','交接清冊']],['company-resources',['company-resources','公司資源','總務管理']]
  ];
  for(const [key,terms] of rules) if(terms.some(t=>raw.includes(String(t).toLowerCase()))) return key;
  return String(item?.id||'').trim()||null;
}

function suggestedPermissions(jobCategories=[],workType='site'){
  const jobs=new Set(jobCategories); let out=new Set();
  if(jobs.has('會計')||jobs.has('財務')) out.add('finance');
  if(jobs.has('總務')) {out.add('company-resources');out.add('manage-templates');}
  if(jobs.has('人事')) out.add('manage-staff');
  if(jobs.has('勤務')) out.add('manage-staff');
  if(jobs.has('社區管理')) {out.add('manage-communities');out.add('view-submissions');}
  if(workType!=='internal' && (jobs.has('社區管理')||jobs.has('秘書')||jobs.has('保全')||jobs.has('機動'))) {['todo','work-journal','committee','residents','vendors','handover'].forEach(x=>out.add(x));out.add('schedule');}
  if(!out.size) out.add(workType==='internal'?'company-resources':'todo');
  return [...out];
}
const $=id=>document.getElementById(id);
let __sopCompanyModulePromise=null;
async function ensureSopCompanyModule(){
  if(window.SOPCompanyModule&&typeof window.SOPCompanyModule.render==='function') return window.SOPCompanyModule;
  if(__sopCompanyModulePromise) return __sopCompanyModulePromise;
  __sopCompanyModulePromise=new Promise((resolve,reject)=>{
    const existing=document.querySelector('script[data-sop-company-module]');
    if(existing){
      existing.addEventListener('load',()=>resolve(window.SOPCompanyModule));
      existing.addEventListener('error',()=>reject(new Error('SOP 模組載入失敗')));
      return;
    }
    const script=document.createElement('script');
    script.src='/modules/sop-company.js?v=12';
    script.async=true;
    script.dataset.sopCompanyModule='1';
    script.onload=()=>window.SOPCompanyModule?resolve(window.SOPCompanyModule):reject(new Error('SOP 模組載入後沒有初始化'));
    script.onerror=()=>reject(new Error('SOP 模組檔案無法載入，請確認 /modules/sop-company.js 已部署'));
    document.head.appendChild(script);
  });
  try{return await __sopCompanyModulePromise;}finally{__sopCompanyModulePromise=null;}
}
