async function openMessageAudit(){try{const d=await api('/api/company/message-audit/search');const box=document.createElement('div');box.className='modal-backdrop';box.innerHTML=`<div class="modal modal-wide message-audit-modal"><button class="modal-close" type="button" onclick="this.closest('.modal-backdrop').remove()">×</button><h2>🔐 訊息稽核</h2><p class="hint">此功能僅提供已授權的稽核人員使用。每次查看都會留下稽核紀錄。</p><div class="audit-search-bar"><input id="auditQ" placeholder="搜尋姓名、員編或訊息內容"><input id="auditFrom" type="date"><span>～</span><input id="auditTo" type="date"><button onclick="runMessageAuditSearch(this)">搜尋</button></div><div id="auditResults"></div></div>`;document.body.appendChild(box);renderMessageAuditResults(box,d.rows||[]);}catch(e){alert(e.message)}}
function renderMessageAuditResults(box,rows){const el=box.querySelector('#auditResults');if(!rows.length){el.innerHTML='<div class="empty">目前沒有符合條件的訊息。</div>';return;}el.innerHTML=`<div class="table-wrap"><table><thead><tr><th>時間</th><th>發送人</th><th>收件人</th><th>訊息</th><th>狀態</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${formatDate(r.created_at)}</td><td>${escapeHtml(r.sender_name)}<br><span class="muted">${escapeHtml(r.sender_employee_id)}</span></td><td>${escapeHtml(r.recipient_name)}<br><span class="muted">${escapeHtml(r.recipient_employee_id)}</span></td><td>${r.message_type==='image'&&r.attachment?.url?`<a href="${escapeAttr(r.attachment.url)}" target="_blank" rel="noopener"><img class="audit-msg-thumb" src="${escapeAttr(r.attachment.url)}" alt="圖片訊息" loading="lazy"></a>${r.body&&r.body!=='[圖片]'?`<div>${escapeHtml(String(r.body).replace(/^\[圖片\]\s*/,''))}</div>`:''}`:r.message_type==='sticker'&&r.attachment?`<span class="tag">貼圖</span> ${escapeHtml(r.attachment.emoji||'')} ${escapeHtml(r.attachment.text||'')}`:escapeHtml(r.body)}</td><td>${r.read_at?'<span class="tag success">已讀</span>':'<span class="tag">未讀</span>'}</td></tr>`).join('')}</tbody></table></div>`;}
