  if(a==='work-journal'){const workspace=$('companyWorkspace');try{if(!window.WorkJournalCompanyModule)throw new Error('工作日誌模組尚未載入，請重新整理頁面');if(!workspace)throw new Error('找不到公司工作頁面。');document.querySelectorAll('[id^="tab-"]').forEach(el=>el.style.display='none');workspace.classList.remove('schedule-workpage');workspace.classList.add('panel');workspace.style.display='block';workspace.innerHTML='<div class="profile-loading">正在讀取資料中，請稍候…</div>';await window.WorkJournalCompanyModule.render(workspace,e.detail?.label||'工作日誌管理');}catch(err){if(workspace){workspace.style.display='block';workspace.innerHTML=`<div class="msg error">${escapeHtml(err?.message||'工作日誌無法開啟')}</div>`;}else alert(err?.message||'工作日誌無法開啟');}return;}
