for(const b of document.querySelectorAll('.nav-tabs button'))b.addEventListener('click',()=>{document.querySelectorAll('.nav-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');for(const id of ['overview','staff','communities','submissions','templates'])$(`tab-${id}`).style.display=b.dataset.tab===id?'block':'none';});
async function loadAll(){const isOwner=state.currentAdminLevel==='owner';const isAdmin=state.currentRole==='company_admin';const jobs=[(isAdmin||state.companyPermissions.includes('manage-staff'))?api('/api/company/admins').catch(()=>({admins:[],current_user_id:null,current_admin_level:state.currentAdminLevel})):Promise.resolve({admins:[],current_user_id:state.currentUserId,current_admin_level:state.currentAdminLevel}),state.companyPermissions.includes('manage-staff')||isAdmin?api('/api/company/staff').catch(()=>[]):Promise.resolve([]),state.companyPermissions.includes('manage-communities')||isAdmin?api('/api/company/communities').catch(()=>[]):Promise.resolve([]),state.companyPermissions.includes('view-submissions')||isAdmin?api('/api/company/submissions').then(x=>{state.submissionForms=x.forms||null;return x.submissions}).catch(()=>[]):Promise.resolve([]),state.companyPermissions.includes('manage-templates')||isAdmin?api('/api/company/templates').catch(()=>({})):Promise.resolve({})];const [adminData,staff,communities,submissions,templateData]=await Promise.all(jobs);state.admins=adminData.admins||[];state.currentUserId=adminData.current_user_id||state.currentUserId;state.currentAdminLevel=adminData.current_admin_level||state.currentAdminLevel;state.staff=staff;state.communities=communities;state.submissions=submissions;state.templates=templateData.companyTemplates||[];state.globalTemplates=templateData.globalTemplates||[];const resources=await api('/api/company/platform-resources').catch(()=>({platformResources:[],companyResources:[]}));state.platformResources=resources.platformResources||[];state.companyResources=resources.companyResources||[];renderAll()}
function renderAll(){renderOverview();renderStaff();renderCommunities();renderSubmissions();renderTemplates()}
function renderOverview(){
  const el=$('tab-overview');
  // 新版首頁：依職位與權限顯示不同卡片
  if(window.CompanyDashboard){window.CompanyDashboard.render(el,{tenantName:state.tenant?.name||''});return;}
  const isAdmin=state.currentRole==='company_admin';
  const cards=[];
  if(isAdmin||state.companyPermissions.includes('manage-staff')) cards.push(`<div class="stat-card"><span>👥 人員</span><strong>${state.staff.filter(x=>x.role==='staff').length}</strong><small>可管理的公司／現場人員</small></div>`);
  if(isAdmin||state.companyPermissions.includes('manage-communities')) cards.push(`<div class="stat-card"><span>🏠 社區</span><strong>${state.communities.filter(x=>x.status==='active').length}</strong><small>啟用中的案場</small></div>`);
  if(isAdmin||state.companyPermissions.includes('view-submissions')) cards.push(`<div class="stat-card"><span>📋 交接</span><strong>${state.submissions.length}</strong><small>本公司正式紀錄</small></div>`);
  const jobs=(state.currentRole==='staff'&&state.currentRole!=='company_admin')?[]:[];
  const myJobs=(state.companyPermissions||[]).map(x=>STAFF_PERMISSIONS.find(p=>p[0]===x)?.[1]).filter(Boolean);
  el.innerHTML=`<div class="panel"><div class="section-title">🏢 歡迎進入公司內勤工作台</div><h2 style="margin:8px 0">${escapeHtml(state.tenant?.name||'')}</h2><p class="hint">這裡是公司內勤工作空間。您的目錄與可處理功能會依工作身分與權限自動顯示。</p>${myJobs.length?`<div class="panel-lite"><strong>目前可處理</strong><p>${escapeHtml(myJobs.join('、'))}</p></div>`:''}</div>${cards.length?`<div class="stats-grid">${cards.join('')}</div>`:''}<div class="panel"><div class="section-title">🔐 工作空間分流</div><div class="guide-grid"><div><strong>🏢 公司內勤</strong><br>會計、總務、人事、勤務、老闆／總經理等公司內部工作，從本頁登入。</div><div><strong>🏠 社區駐點</strong><br>經理、秘書、保全等駐點工作，請從一般人員入口登入。</div><div><strong>🧩 權限依職務</strong><br>沒有授權的目錄與資料不會顯示；後端 API 也會再次檢查權限。</div><div><strong>🔗 內勤＋兼任駐點</strong><br>同一個人可以分別使用兩個入口，兩邊資料範圍互不混用。</div></div></div>`;
}

function closeCompanyModal(el){const box=typeof el==='string'?$(el):el?.closest?.('.modal-backdrop')||el;if(box){box.remove();document.body.classList.remove('modal-open')}}
function openCompanyModal(title,content,wide=false){const box=document.createElement('div');box.className='modal-backdrop';box.innerHTML=`<div class="modal${wide?' modal-wide':''}" role="dialog" aria-modal="true"><button class="modal-close" type="button" aria-label="關閉">×</button><h2>${title}</h2>${content}</div>`;document.body.appendChild(box);document.body.classList.add('modal-open');box.querySelector('.modal-close').addEventListener('click',()=>closeCompanyModal(box));box.addEventListener('click',e=>{if(e.target===box)closeCompanyModal(box)});return box}
function openAddCompanyAdminModal(){const box=openCompanyModal('🔐 開通公司管理員',`<div class="modal-note">例如老闆可以建立總經理帳號。總經理登入後可代為處理總務、會計與一般人員帳號管理。</div><form id="modalAddAdminForm"><div class="editor-grid"><div><label>管理員員編${state.loginMode==='mobile'?'（可不填）':''}</label><input id="newAdminId" placeholder="例如 CA1002" ${state.loginMode==='mobile'?'':'required'}></div><div><label>手機號碼${state.loginMode==='mobile'?'（登入帳號）':''}</label><input id="newAdminMobile" inputmode="tel" placeholder="0912345678" ${state.loginMode==='mobile'?'required':''}></div><div><label>姓名</label><input id="newAdminName" placeholder="例如 王總經理" required></div><div><label>初始密碼</label><input id="newAdminPass" type="password" placeholder="至少 4 碼" required></div></div><div class="modal-actions"><button type="button" class="secondary" onclick="closeCompanyModal(this)">取消</button><button type="submit">開通公司管理員</button></div></form>`);box.querySelector('#modalAddAdminForm').addEventListener('submit',addCompanyAdmin)}
async function openAddStaff(){
 const communityHtml=state.communities.map(c=>`<label class="check-row"><input type="checkbox" data-new-cid="${c.id}"> ${escapeHtml(c.name)}</label>`).join('');
 const jobHtml=JOB_CATEGORIES.map(x=>`<label class="check-row"><input type="checkbox" data-new-job="${escapeAttr(x)}"> ${escapeHtml(x)}</label>`).join('');
 const catalog=await loadPermissionCatalog();
 const permissionHtml=`<div class="workspace-permission-group"><div class="workspace-permission-title">🏢 內勤工作項目</div><div class="check-list" id="newCompanyPerms">${permissionOptionsHtml(catalog.company,new Set(),'new')}</div>${sensitivePermHtml(new Set(),'new')}</div><div class="workspace-permission-group"><div class="workspace-permission-title">🏠 駐點工作項目</div><div class="check-list" id="newSitePerms">${permissionOptionsHtml(catalog.site,new Set(),'new')}</div></div>`;
 const box=openCompanyModal('👤 開通一般人員',`<p class="hint">依人員類型分開顯示可開通的工作項目。內勤＋兼任駐點會同時顯示兩區。</p><form id="modalAddStaffForm"><div class="editor-grid"><div><label>員編${state.loginMode==='mobile'?'（可不填）':''}</label><input id="newEmployeeId" placeholder="例如 A002" ${state.loginMode==='mobile'?'':'required'}></div><div><label>手機號碼${state.loginMode==='mobile'?'（登入帳號）':''}</label><input id="newStaffMobile" inputmode="tel" placeholder="0912345678" ${state.loginMode==='mobile'?'required':''}></div><div><label>姓名</label><input id="newStaffName" placeholder="例如 王小明" required></div><div><label>初始密碼</label><input id="newStaffPass" type="password" placeholder="至少 4 碼" required></div><div><label>人員類型</label><select id="newWorkType"><option value="site">駐點人員</option><option value="internal">內勤人員</option><option value="hybrid">內勤＋兼任駐點</option></select></div><div><label>職務位階</label><select id="newJobLevel">${JOB_LEVELS.map(x=>`<option value="${escapeAttr(x)}">${escapeHtml(x)}</option>`).join('')}</select></div></div><div class="panel-lite"><strong>🧩 職務類別（可複選）</strong><div class="check-list">${jobHtml}</div></div><div class="panel-lite"><strong>🏠 所屬案場（可複選）</strong><p class="hint">內勤可不選；駐點或兼任駐點至少勾選一個案場。</p><div class="check-list" id="newCommunityList">${communityHtml||'<div class="empty">目前尚未建立社區。</div>'}</div></div><div class="panel-lite"><strong>🔐 工作台可處理事項</strong><p class="hint">依人員類型分區；切換類型時只顯示對應工作空間。</p>${permissionHtml}</div><div class="modal-actions"><button type="button" class="secondary" onclick="closeCompanyModal(this)">取消</button><button type="submit">開通一般人員</button></div></form>`,true);
 const type=box.querySelector('#newWorkType'); const companyBox=box.querySelector('#newCompanyPerms').closest('.workspace-permission-group'); const siteBox=box.querySelector('#newSitePerms').closest('.workspace-permission-group'); const sync=()=>{companyBox.style.display=type.value==='site'?'none':'block';siteBox.style.display=type.value==='internal'?'none':'block';const internal=type.value==='internal';const list=box.querySelector('#newCommunityList');list.style.opacity=internal?'0.5':'1';list.querySelectorAll('input[data-new-cid]').forEach(x=>{x.disabled=internal;if(internal)x.checked=false;});};type.addEventListener('change',sync);sync();
 box.querySelector('#modalAddStaffForm').addEventListener('submit',addStaff);
}
function renderStaff(){
 const el=$('tab-staff');
 const adminRows=state.admins.map(u=>{const self=Number(u.id)===Number(state.currentUserId);const canEdit=state.currentAdminLevel==='owner' && !self;return `<tr><td><strong>${escapeHtml(u.employee_id)}</strong></td><td><input id="admin-name-${u.id}" value="${escapeAttr(u.name)}" ${canEdit?'':'disabled'}></td><td><span class="tag ${u.admin_level==='owner'?'gold':'success'}">${u.admin_level==='owner'?'公司負責人｜完整權限':'公司管理員'}</span></td><td><select id="admin-active-${u.id}" ${canEdit?'':'disabled'}><option value="1" ${u.is_active?'selected':''}>啟用</option><option value="0" ${!u.is_active?'selected':''}>停用</option></select></td><td><button class="secondary" onclick="openOrgStaff(${u.id})">職位</button> ${self?'<span class="muted">目前登入帳號</span>':(canEdit?`<button class="secondary" onclick="resetStaffPassword(${u.id})">🔑 重設密碼</button> `+`<button class="secondary" onclick="saveCompanyAdmin(${u.id})">儲存</button> <button class="secondary" onclick="changeStaffStatus(${u.id},'disabled')">停用</button> <button class="danger" onclick="changeStaffStatus(${u.id},'left')">離職封存</button> <button class="danger" onclick="changeStaffStatus(${u.id},'blacklist')">黑名單</button>`:'<span class="muted">僅公司負責人可管理</span>')}</td></tr>`}).join('');
 const staffRows=state.staff.filter(u=>u.role==='staff').map(u=>{const type=u.work_type==='hybrid'?'內勤＋兼任駐點':u.work_type==='internal'?'內勤':'駐點';return `<tr><td><strong>${escapeHtml(u.employee_id)}</strong></td><td><input id="staff-name-${u.id}" value="${escapeAttr(u.name)}"></td><td>${escapeHtml(u.position||'尚未設定')}</td><td><span class="tag ${u.work_type==='internal'?'gold':'success'}">${type}</span></td><td><button class="secondary" onclick="openOrgStaff(${u.id})">設定職位／案場</button></td><td><span class="tag ${u.is_active?'success':'gold'}">${u.person_status==='disabled'?'停用':'在職'}</span></td><td><button class="secondary" onclick="saveStaff(${u.id})">儲存</button> <button class="secondary" onclick="resetStaffPassword(${u.id})">🔑 重設密碼</button> <button class="secondary" onclick="changeStaffStatus(${u.id},'disabled')">停用</button> <button class="danger" onclick="changeStaffStatus(${u.id},'left')">離職封存</button> <button class="danger" onclick="changeStaffStatus(${u.id},'blacklist')">黑名單</button></td></tr>`}).join('');
 const adminCreate=state.currentAdminLevel==='owner'?`<div class="panel"><div class="section-title">＋ 新增公司管理員</div><p class="hint">公司負責人可以建立其他公司管理員；公司管理員本身與現場一般人員是兩套工作入口。</p><button onclick="openAddCompanyAdminModal()">＋ 開通公司管理員</button></div>`:'';
 el.innerHTML=`<div id="orgPanel"></div>${adminCreate}<div class="panel"><div class="section-title">🔐 公司管理員（${state.admins.length} 人）</div><p class="hint">公司負責人不可由其他公司管理員停用；其他管理員可由公司負責人管理。</p><div class="table-wrap"><table><thead><tr><th>員編</th><th>姓名</th><th>角色</th><th>狀態</th><th>操作</th></tr></thead><tbody>${adminRows||'<tr><td colspan="5" class="empty">目前沒有公司管理員。</td></tr>'}</tbody></table></div></div><div class="panel"><div class="section-title">👥 一般人員（${state.staff.filter(x=>x.role==='staff').length} 人）</div><p class="hint">開通時只要選「職位」與所屬社區（或區域、班別），工作地點、排班方式與工作台權限會依職位自動帶入。登入帳號可以用員編或手機，第一次登入會要求本人改密碼。</p><button onclick="openOrgStaff()">＋ 開通人員</button><div class="table-wrap"><table><thead><tr><th>員編</th><th>姓名</th><th>職務</th><th>類型</th><th>設定</th><th>狀態</th><th>操作</th></tr></thead><tbody>${staffRows||'<tr><td colspan="7" class="empty">目前尚未開通一般人員。</td></tr>'}</tbody></table></div></div><div class="panel"><div class="section-title">📦 人員管理｜封存／永不錄用</div><p class="hint">離職與黑名單會刪除登入帳號、釋放原員編，但人事資料會保留在這裡供人事查閱；停用則保留帳號，可日後復職。</p><div class="archive-actions"><button class="secondary" onclick="loadArchive('left')">封存（離職）</button><button class="secondary" onclick="loadArchive('blacklist')">永不錄用（黑名單）</button></div><div id="personArchiveList" class="archive-list"></div></div>`;
 window.OrgCompanyModule?.renderPanel($('orgPanel'),{onChange:()=>loadAll()});
}
function openOrgStaff(id){if(!window.OrgCompanyModule){alert('組織模組尚未載入，請重新整理頁面');return;}window.OrgCompanyModule.openStaffForm(id||null,{onDone:()=>loadAll()}).catch(err=>alert(err.message));}
async function resetStaffPassword(id){const u=[...state.staff,...state.admins].find(x=>Number(x.id)===Number(id));try{await window.OrgCompanyModule.resetPassword(id,u?.name);}catch(err){alert(err.message)}}
async function changeStaffStatus(id,status){const label=status==='disabled'?'停用':status==='left'?'離職並封存':'加入黑名單並封存';if(!confirm(`確定要將這位人員設定為「${label}」嗎？${status==='left'||status==='blacklist'?'\n登入帳號會刪除，但人事資料會封存，原員編可供新進人員使用。':''}`))return;try{await api(`/api/company/staff/${id}/status`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});await loadAll();alert('人員狀態已更新。')}catch(err){alert(err.message)}}
async function loadArchive(status){try{const rows=await api(`/api/company/personnel-archive?status=${encodeURIComponent(status)}`);$('personArchiveList').innerHTML=rows.length?rows.map(r=>`<div class="archive-card"><strong>${escapeHtml(r.employee_id)}｜${escapeHtml(r.name)}</strong><span>${r.person_status==='blacklist'?'永不錄用':'封存'}</span><small>封存時間：${formatDate(r.archived_at)}</small><small>原工作：${escapeHtml((r.snapshot?.job_categories||[]).join('、'))}｜案場：${escapeHtml((r.snapshot?.communities||[]).map(x=>x.name).join('、')||'無')}</small></div>`).join(''):'<div class="empty">目前沒有資料。</div>'}catch(err){alert(err.message)}}
async function addCompanyAdmin(e){e.preventDefault();try{await api('/api/company/admins',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({employee_id:$('newAdminId').value,mobile:$('newAdminMobile')?.value||'',name:$('newAdminName').value,password:$('newAdminPass').value})});closeCompanyModal(e.target.closest('.modal-backdrop'));await loadAll();alert('公司管理員帳號已開通。')}catch(err){alert(err.message)}}
async function saveCompanyAdmin(id){try{await api(`/api/company/admins/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$(`admin-name-${id}`).value,is_active:$(`admin-active-${id}`).value==='1',password:$(`admin-pass-${id}`).value})});await loadAll();alert('公司管理員資料已更新。')}catch(err){alert(err.message)}}
async function addStaff(e){e.preventDefault();try{const ids=[...e.target.querySelectorAll('input[data-new-cid]:checked')].map(x=>Number(x.dataset.newCid));const jobs=[...e.target.querySelectorAll('input[data-new-job]:checked')].map(x=>x.dataset.newJob);const permissions=withSubPerms(e.target,[...e.target.querySelectorAll('input[data-new-perm]:checked')].map(x=>x.dataset.newPerm));const r=await api('/api/company/staff',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({employee_id:$('newEmployeeId').value,mobile:$('newStaffMobile')?.value||'',name:$('newStaffName').value,password:$('newStaffPass').value,work_type:$('newWorkType').value,job_categories:jobs,job_level:$('newJobLevel').value,permissions,community_ids:ids})});closeCompanyModal(e.target.closest('.modal-backdrop'));await loadAll();alert('已開通人員帳號，內勤／駐點、案場、職務與工作台權限已建立。')}catch(err){alert(err.message)}}
async function openStaffSettings(id){
 const u=state.staff.find(x=>Number(x.id)===Number(id)); if(!u)return;
 const rows=await api(`/api/company/staff/${id}/communities`);
 const communityHtml=rows.map(c=>`<label class="check-row"><input type="checkbox" data-edit-cid="${c.id}" ${c.assigned?'checked':''} ${c.status!=='active'?'disabled':''}> ${escapeHtml(c.name)}${c.status!=='active'?'（已停用）':''}</label>`).join('');
 const selectedJobs=new Set(Array.isArray(u.job_categories)&&u.job_categories.length?u.job_categories:(u.job_category?[u.job_category]:[]));
 const jobHtml=JOB_CATEGORIES.map(x=>`<label class="check-row"><input type="checkbox" data-edit-job="${escapeAttr(x)}" ${selectedJobs.has(x)?'checked':''}> ${escapeHtml(x)}</label>`).join('');
 const selected=new Set(Array.isArray(u.permissions)&&u.permissions.length?u.permissions:suggestedPermissions([...selectedJobs],u.work_type||'site'));
 const catalog=await loadPermissionCatalog();
 const companyHtml=permissionOptionsHtml(catalog.company,selected,'edit');
 const siteHtml=permissionOptionsHtml(catalog.site,selected,'edit');
 const box=openCompanyModal(`👤 ${escapeHtml(u.name)}｜職務／案場／權限`,`<div class="editor-grid"><div><label>人員類型</label><select id="editWorkType"><option value="site" ${u.work_type==='site'?'selected':''}>駐點人員</option><option value="internal" ${u.work_type==='internal'?'selected':''}>內勤人員</option><option value="hybrid" ${u.work_type==='hybrid'?'selected':''}>內勤＋兼任駐點</option></select></div><div><label>職務位階</label><select id="editJobLevel">${JOB_LEVELS.map(x=>`<option value="${escapeAttr(x)}" ${u.job_level===x?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select></div></div><div class="panel-lite"><strong>🧩 職務類別（可複選）</strong><div class="check-list">${jobHtml}</div></div><div class="panel-lite"><strong>🏠 所屬案場（可複選）</strong><div class="check-list" id="editCommunityList">${communityHtml||'<div class="empty">目前尚未建立社區。</div>'}</div></div><div class="panel-lite"><strong>🔐 工作台可處理事項</strong><p class="hint">依人員類型分區；內勤＋兼任駐點會同時顯示兩區。</p><div id="editCompanyPermGroup" class="workspace-permission-group"><div class="workspace-permission-title">🏢 內勤工作項目</div><div class="check-list">${companyHtml}</div>${sensitivePermHtml(selected,'edit')}</div><div id="editSitePermGroup" class="workspace-permission-group"><div class="workspace-permission-title">🏠 駐點工作項目</div><div class="check-list">${siteHtml}</div></div></div><div class="modal-actions"><button type="button" class="secondary" onclick="closeCompanyModal(this)">取消</button><button type="button" onclick="saveStaffSettings(${id},this)">儲存設定</button></div>`,true);
 const type=box.querySelector('#editWorkType'),list=box.querySelector('#editCommunityList'),companyGroup=box.querySelector('#editCompanyPermGroup'),siteGroup=box.querySelector('#editSitePermGroup');
 const sync=()=>{companyGroup.style.display=type.value==='site'?'none':'block';siteGroup.style.display=type.value==='internal'?'none':'block';const internal=type.value==='internal';list.style.opacity=internal?'0.5':'1';list.querySelectorAll('input[data-edit-cid]').forEach(x=>{x.disabled=internal||x.closest('label').textContent.includes('已停用');if(internal)x.checked=false;});}; type.addEventListener('change',sync); sync();
}
async function saveStaffSettings(id,btn){const box=btn.closest('.modal');const communityIds=[...box.querySelectorAll('input[data-edit-cid]:checked')].map(x=>Number(x.dataset.editCid));const jobs=[...box.querySelectorAll('input[data-edit-job]:checked')].map(x=>x.dataset.editJob);const permissions=withSubPerms(box,[...box.querySelectorAll('input[data-edit-perm]:checked')].map(x=>x.dataset.editPerm));try{await api(`/api/company/staff/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({work_type:box.querySelector('#editWorkType').value,job_categories:jobs,job_level:box.querySelector('#editJobLevel').value,permissions,community_ids:communityIds})});closeCompanyModal(btn);await loadAll();alert('職務、案場與工作台權限已更新。')}catch(err){alert(err.message)}}

function renderCommunities(){const el=$('tab-communities');setTimeout(()=>window.OrgCompanyModule?.renderRegions($('regionPanel'),{onChange:()=>{}}),0);el.innerHTML=`<div id="regionPanel"></div><div class="panel"><div class="section-title">🏠 社區管理</div><p class="hint">新增社區會在目前畫面中央開啟設定視窗。</p><button onclick="openAddCommunityModal()">＋ 新增社區</button></div><div class="panel"><div class="section-title">本公司社區（${state.communities.length} 個）</div><div class="table-wrap"><table><thead><tr><th>社區名稱</th><th>代表地址</th><th>狀態</th><th>操作</th></tr></thead><tbody>${state.communities.map(c=>`<tr><td><input id="community-name-${c.id}" value="${escapeAttr(c.name)}"></td><td><input id="community-addr-${c.id}" value="${escapeAttr(c.main_address||'')}" placeholder="例如：範例市幸福區和平路100號"></td><td><select id="community-status-${c.id}"><option value="active" ${c.status==='active'?'selected':''}>服務中</option><option value="inactive" ${c.status!=='active'?'selected':''}>已結束服務／停用</option></select></td><td><button class="secondary" onclick="saveCommunity(${c.id})">儲存</button> <button class="danger" onclick="toggleCommunityService(${c.id},${c.status==='active'?'true':'false'})">${c.status==='active'?'結束服務':'恢復服務'}</button></td></tr>`).join('')}</tbody></table></div></div>`}
function openAddCommunityModal(){const box=openCompanyModal('＋ 新增社區',`<form id="addCommunityForm"><div class="field"><label>社區名稱</label><input id="newCommunityName" required placeholder="例如：幸福花園"></div><div class="field"><label>代表地址（社區主要地址）</label><input id="newCommunityAddr" placeholder="例如：範例市幸福區和平路100號"></div><p class="hint">社區有多個門牌（例如前棟、後棟）時，由駐點經理或秘書第一次使用住戶名冊時，在「社區棟別門牌設定」逐棟設定。</p><div class="modal-actions"><button type="submit">新增社區</button></div></form>`);(box?.querySelector?box:document).querySelector('#addCommunityForm').addEventListener('submit',addCommunity);}
async function addCommunity(e){e.preventDefault();try{await api('/api/company/communities',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('newCommunityName').value,main_address:$('newCommunityAddr')?.value||''})});closeCompanyModal(e.target.closest('.modal-backdrop'));await loadAll();alert('已新增社區。')}catch(err){alert(err.message)}}
async function saveCommunity(id){try{await api(`/api/company/communities/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$(`community-name-${id}`).value,main_address:$(`community-addr-${id}`)?.value??undefined,status:$(`community-status-${id}`).value==='active'})});await loadAll();alert('社區設定已儲存。')}catch(err){alert(err.message)}}
async function toggleCommunityService(id,isActive){
  const c=state.communities.find(x=>Number(x.id)===Number(id)); if(!c)return;
  if(isActive){
    if(!confirm(`確定要結束「${c.name}」的服務嗎？\n\n系統不會刪除歷史資料；社區會改為停用狀態，新的班表、出勤與巡邏作業將不再以此社區為可用案場。未來可以恢復服務。`))return;
  }else{
    if(!confirm(`要恢復「${c.name}」的服務嗎？\n\n恢復後可再次進行人員派駐、班表與出勤／巡邏設定。`))return;
  }
  try{await api(`/api/company/communities/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:c.name,status:!isActive})});await loadAll();alert(isActive?'已結束服務，歷史資料已保留。':'已恢復服務。')}catch(err){alert(err.message)}
}
// 交接紀錄：經理版／秘書版分開顯示，可檢視內容、產生 Word、刪除
const HANDOVER_LABELS={manager:'👔 經理交接清冊',secretary:'🗂 秘書交接清冊'};
function submissionPeople(s){const d=s.data||{};return s.form_type==='secretary'?[d.outgoing_secretary,d.incoming_secretary]:[d.outgoing_manager,d.incoming_manager];}
function renderSubmissions(){const el=$('tab-submissions');if(!state.submissions.length){el.innerHTML='<div class="panel empty">目前還沒有正式送出的交接紀錄。</div>';return}
  const type=state.submissionType||'';const list=state.submissions.filter(s=>!type||(s.form_type||'manager')===type);
  const count=t=>state.submissions.filter(s=>(s.form_type||'manager')===t).length;
  const opts=state.templates.map(t=>`<option value="${t.id}" ${t.is_active?'selected':''}>${escapeHtml(t.name)}${t.is_active?'（預設）':''}</option>`).join('');
  el.innerHTML=`<div class="panel"><div class="section-title">📋 本公司正式交接紀錄（${state.submissions.length} 筆）</div><div class="ho-filter" style="display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 12px">${[['','全部',state.submissions.length],['manager',HANDOVER_LABELS.manager,count('manager')],['secretary',HANDOVER_LABELS.secretary,count('secretary')]].map(([k,l,n])=>`<button type="button" class="${type===k?'':'secondary'}" onclick="filterSubmissions('${k}')">${l}（${n}）</button>`).join('')}</div>
  <div class="table-wrap"><table><thead><tr><th>編號</th><th>類型</th><th>送出時間</th><th>填寫人員</th><th>社區</th><th>交接人員</th><th>操作</th></tr></thead><tbody>${list.map(s=>{const [a,b]=submissionPeople(s);return `<tr><td>${s.id}</td><td>${HANDOVER_LABELS[s.form_type||'manager']||'交接清冊'}</td><td>${formatDate(s.created_at)}</td><td>${escapeHtml(s.employee_name||'')}<br><span class="muted">${escapeHtml(s.employee_id||'')}</span></td><td>${escapeHtml(s.community_name||s.data.community_name||'')}</td><td>${escapeHtml(a||'')} → ${escapeHtml(b||'')}</td><td style="white-space:nowrap"><button class="secondary" onclick="viewSubmission(${s.id})">檢視</button> ${state.templates.length>1?`<select id="tpl-${s.id}" style="width:auto;display:inline-block;margin:0">${opts}</select> `:''}<button class="secondary" onclick="downloadDocx(${s.id})" ${state.templates.length?'':'disabled title="請先到「公司文件／範本」上傳 Word 範本"'}>產生 Word</button> <button class="danger" onclick="deleteSubmission(${s.id})">刪除</button></td></tr>`}).join('')||'<tr><td colspan="7" class="muted">這個類型目前沒有紀錄。</td></tr>'}</tbody></table></div>${state.templates.length>1?'<p class="hint">經理版與秘書版欄位不同，產生 Word 時請選擇對應的範本。</p>':''}</div>`}
function filterSubmissions(t){state.submissionType=t;renderSubmissions()}
function submissionAnswer(q,v){if(Array.isArray(v))return v.join('、');if(v===undefined||v===null||v==='')return '';return String(v)+(q?.type==='money'?' 元':'');}
function viewSubmission(id){
  const s=state.submissions.find(x=>x.id===id);if(!s)return;const form=(state.submissionForms||{})[s.form_type||'manager']||{pages:[],questions:[]};const d=s.data||{};
  const known=new Set(form.questions.map(q=>q.id));
  const body=form.pages.map(p=>{const qs=form.questions.filter(q=>q.pageId===p.id&&d[q.id]!==undefined&&submissionAnswer(q,d[q.id])!=='');if(!qs.length)return '';return `<h3 style="margin:16px 0 6px">${escapeHtml(p.title)}</h3><table><tbody>${qs.map(q=>`<tr><th style="width:36%;text-align:left">${escapeHtml(q.label)}</th><td style="white-space:pre-wrap">${escapeHtml(submissionAnswer(q,d[q.id]))}</td></tr>`).join('')}</tbody></table>`;}).join('');
  const extra=Object.entries(d).filter(([k,v])=>!known.has(k)&&!k.startsWith('__')&&submissionAnswer(null,v)!=='');
  const modal=document.createElement('div');modal.className='modal-backdrop';
  modal.innerHTML=`<div class="modal" role="dialog" aria-modal="true" style="max-width:760px;width:min(760px,96vw);max-height:90vh;overflow:auto"><button type="button" class="modal-close" aria-label="關閉">×</button><div class="eyebrow">${HANDOVER_LABELS[s.form_type||'manager']||''}｜單號 ${s.id}</div><h2>${escapeHtml(s.community_name||d.community_name||'')}</h2><p class="hint">${escapeHtml(s.employee_name||'')} 於 ${formatDate(s.created_at)} 送出</p>${body||'<p class="muted">沒有填寫內容。</p>'}${extra.length?`<h3 style="margin:16px 0 6px">其他欄位（題目已調整或刪除）</h3><table><tbody>${extra.map(([k,v])=>`<tr><th style="width:36%;text-align:left">${escapeHtml(k)}</th><td style="white-space:pre-wrap">${escapeHtml(submissionAnswer(null,v))}</td></tr>`).join('')}</tbody></table>`:''}</div>`;
  document.body.appendChild(modal);const close=()=>modal.remove();modal.querySelector('.modal-close').onclick=close;modal.addEventListener('click',e=>{if(e.target===modal)close();});
}
function downloadDocx(id){const v=$(`tpl-${id}`)?.value||'';window.open(`/api/company/generate/${id}${v?`?templateId=${encodeURIComponent(v)}`:''}`,'_blank')}
async function deleteSubmission(id){if(!confirm('確定刪除這筆正式交接紀錄嗎？刪除後無法復原。'))return;try{await api(`/api/company/submissions/${id}`,{method:'DELETE'});state.submissions=state.submissions.filter(s=>s.id!==id);renderSubmissions()}catch(err){alert(err.message)}}
window.filterSubmissions=filterSubmissions;window.viewSubmission=viewSubmission;window.downloadDocx=downloadDocx;window.deleteSubmission=deleteSubmission;
function renderTemplates(){
  const el=$('tab-templates');
  const globalRows=state.globalTemplates.map(t=>`<tr><td><strong>${escapeHtml(t.name)}</strong></td><td>${formatDate(t.created_at)}</td><td>${t.is_active?'<span class="tag gold">平台預設</span>':'平台範本'}</td><td><button class="secondary" onclick="adoptTemplate(${t.id})">＋ 使用這份範本</button></td></tr>`).join('');
  const companyRows=state.templates.map(t=>`<tr><td><strong>${escapeHtml(t.name)}</strong></td><td>${t.is_active?'<span class="tag gold">目前公司預設</span>':'未啟用'}</td><td>${formatDate(t.created_at)}</td><td><button class="secondary" onclick="activateTemplate(${t.id})" ${t.is_active?'disabled':''}>設為公司預設</button> <button class="secondary" onclick="renameTemplate(${t.id},'${escapeAttr(t.name)}')">改名稱</button> <button class="secondary" onclick="replaceTemplate(${t.id})">更新檔案</button> <button class="danger" onclick="deleteTemplate(${t.id})">刪除</button></td></tr>`).join('');
  el.innerHTML=`
  <div class="panel"><div class="section-title">📄 公司制式文件／Word 範本</div>
    <p class="hint">公司可以直接採用平台提供的標準範本，也可以上傳自己的版本。平台範本不會被公司修改；按「使用這份範本」後會複製成公司的版本，之後即可自行改名、更新檔案、設為預設或刪除。</p>
  </div>
  <div class="panel"><div class="section-title">📚 平台公版文件（${state.platformResources.length} 份）</div><p class="hint">這裡是一般工作文件，不限於交接 Word 範本，例如住戶名冊 Excel、PDF、Word、PowerPoint、TXT、CSV。公司可以先下載確認，也可以直接建立成公司的資源副本。</p>${state.platformResources.length?`<div class="table-wrap"><table><thead><tr><th>名稱</th><th>分類</th><th>格式</th><th>說明</th><th>操作</th></tr></thead><tbody>${state.platformResources.map(r=>`<tr><td><strong>${escapeHtml(r.name)}</strong></td><td>${escapeHtml(r.category||'')}</td><td>${escapeHtml(r.extension||'')}</td><td>${escapeHtml(r.description||'')}</td><td><button class="secondary" onclick="downloadPlatformResource(${r.id})">下載</button> <button class="secondary" onclick="adoptPlatformResource(${r.id})">＋ 採用到公司資源</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">目前平台尚未提供一般公版文件。</div>'}</div>
  <div class="panel"><div class="section-title">🏢 本公司已採用的平台公版（${state.companyResources.length} 份）</div>${state.companyResources.length?`<div class="table-wrap"><table><thead><tr><th>名稱</th><th>分類</th><th>格式</th><th>建立時間</th><th>操作</th></tr></thead><tbody>${state.companyResources.map(r=>`<tr><td><strong>${escapeHtml(r.name)}</strong></td><td>${escapeHtml(r.category||'')}</td><td>${escapeHtml(r.extension||'')}</td><td>${formatDate(r.created_at)}</td><td><button class="secondary" onclick="downloadCompanyResource(${r.id})">下載</button> <button class="danger" onclick="deleteCompanyResource(${r.id})">刪除</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚未採用平台公版文件。</div>'}</div>
  <div class="panel"><div class="section-title">🏛 平台提供的制式範本（${state.globalTemplates.length} 份）</div>
    ${state.globalTemplates.length?`<div class="table-wrap"><table><thead><tr><th>範本名稱</th><th>建立時間</th><th>狀態</th><th>操作</th></tr></thead><tbody>${globalRows}</tbody></table></div>`:'<div class="empty">目前平台尚未提供制式範本。</div>'}
  </div>
  <div class="panel"><div class="section-title">🏢 本公司範本（${state.templates.length} 份）</div>
    <form id="uploadForm"><div class="row"><input type="text" id="tplName" placeholder="例如：○○物業公司交接清冊標準版" required><input type="file" id="tplFile" accept=".docx" required></div><button type="submit">＋ 上傳公司 Word 範本</button></form>
    ${state.templates.length?`<div class="table-wrap"><table><thead><tr><th>名稱</th><th>狀態</th><th>建立時間</th><th>操作</th></tr></thead><tbody>${companyRows}</tbody></table></div>`:'<div class="empty">尚未建立公司範本。您可以從上方平台範本直接「使用」，或自行上傳。</div>'}
  </div>`;
  $('uploadForm').addEventListener('submit',async e=>{e.preventDefault();try{const fd=new FormData();fd.append('name',$('tplName').value);fd.append('template',$('tplFile').files[0]);await api('/api/company/templates',{method:'POST',body:fd});await loadAll();alert('公司範本已上傳。')}catch(err){alert(err.message)}})
}
async function adoptTemplate(id){if(!confirm('要把這份平台制式範本複製成您公司的版本嗎？複製後即可自行修改、更新或刪除。'))return;try{await api(`/api/company/templates/${id}/adopt`,{method:'POST'});await loadAll();alert('已建立公司版本，您現在可以自行管理。')}catch(err){alert(err.message)}}
async function activateTemplate(id){try{await api(`/api/company/templates/${id}/activate`,{method:'POST'});await loadAll()}catch(err){alert(err.message)}}
async function renameTemplate(id,current){const name=prompt('請輸入新的公司範本名稱：',current);if(name===null)return;if(!name.trim()){alert('名稱不可空白');return}try{await api(`/api/company/templates/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.trim()})});await loadAll()}catch(err){alert(err.message)}}
async function replaceTemplate(id){const input=document.createElement('input');input.type='file';input.accept='.docx';input.onchange=async()=>{if(!input.files[0])return;try{const fd=new FormData();fd.append('template',input.files[0]);await api(`/api/company/templates/${id}/replace`,{method:'POST',body:fd});await loadAll();alert('公司範本檔案已更新。')}catch(err){alert(err.message)}};input.click()}
async function deleteTemplate(id){if(!confirm('確定刪除這份公司範本嗎？平台原始範本不會受影響。'))return;try{await api(`/api/company/templates/${id}`,{method:'DELETE'});await loadAll()}catch(err){alert(err.message)}}
function formatDate(s){return new Date(s).toLocaleString('zh-TW',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}
function escapeHtml(str){return String(str??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function escapeAttr(s){return escapeHtml(s)}
boot();

// V4.3.0：按 ESC 關閉目前的懸浮視窗
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const boxes=document.querySelectorAll('.modal-backdrop');if(boxes.length){const box=boxes[boxes.length-1];box.remove();document.body.classList.remove('modal-open')}}});

// 班表模組 UI：保持獨立，不修改既有全站 CSS。
(function(){if(document.getElementById('scheduleModuleStyles'))return;const s=document.createElement('style');s.id='scheduleModuleStyles';s.textContent=`.schedule-toolbar{display:grid;grid-template-columns:repeat(4,minmax(140px,1fr));gap:12px;align-items:end;margin-bottom:14px}.schedule-toolbar label,.editor-grid label{display:block;font-size:13px;color:#567;margin-bottom:5px}.schedule-toolbar input,.schedule-toolbar select,.editor-grid input,.editor-grid select,.editor-grid textarea,.modal textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #DAD2CF;border-radius:9px;background:#fff}.schedule-toolbar button{min-height:40px}.schedule-rule-note{padding:12px 14px;background:#F6F3EE;border:1px solid #E6DDD9;border-radius:10px;margin-bottom:14px;line-height:1.7}.schedule-grid-wrap{max-height:62vh;overflow:auto}.schedule-grid{min-width:900px;border-collapse:separate;border-spacing:0}.schedule-grid th,.schedule-grid td{padding:7px 6px;text-align:center;border-right:1px solid #ECE8E6;border-bottom:1px solid #ECE8E6;font-size:12px}.schedule-grid thead th{position:sticky;top:0;background:#F8F6F5;z-index:2}.schedule-grid tbody th{position:sticky;left:0;background:#fff;text-align:left;z-index:1;white-space:nowrap}.schedule-grid td.work{background:#F6F3EF}.schedule-grid td.off{background:#fff0f0;color:#a63b3b;font-weight:700}.schedule-grid td.leave{background:#fff8df;color:#8a6500;font-weight:700}.schedule-grid td.night{background:#eef0ff;color:#3f4d91;font-weight:700}.schedule-alerts{margin-top:12px;padding:10px 12px;background:#fff6e8;border:1px solid #eed7aa;border-radius:10px}.schedule-rule-tabs{display:flex;gap:8px;margin-bottom:14px}.schedule-rule-tabs button{border:1px solid #DAD2CF;background:#fff;border-radius:9px;padding:8px 14px}.schedule-rule-tabs button:hover{background:#F6F3EE}@media(max-width:800px){.schedule-toolbar{grid-template-columns:1fr 1fr}.schedule-toolbar button{grid-column:1/-1}}`;document.head.appendChild(s)})();
(function(){if(document.getElementById('scheduleWorkpageStyles'))return;const s=document.createElement('style');s.id='scheduleWorkpageStyles';s.textContent=`#companyWorkspace.schedule-workpage{display:block!important;padding:24px;min-height:60vh}.schedule-page-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;border-bottom:1px solid #E6E1DF;padding-bottom:16px;margin-bottom:18px}.schedule-page-heading h2{margin:0 0 6px;color:#472823}.schedule-page-heading p{margin:0;color:#766661}.schedule-page-nav{display:flex;gap:8px;flex-wrap:wrap}.schedule-page-nav button:disabled{background:#472823;color:white;opacity:1}.schedule-workpage .modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}.schedule-workpage .schedule-rule-tabs{margin-top:10px}.schedule-workpage .panel-lite{margin:12px 0}@media(max-width:800px){#companyWorkspace.schedule-workpage{padding:14px}.schedule-page-nav button{font-size:13px}}`;document.head.appendChild(s)})();
// ===== 智慧班表模組 V1 前台 =====
const SCHEDULE_CATEGORIES=[['admin','行政'],['security','保全'],['mobile','機動']];
let scheduleCache={staff:[],communities:[]};
function scheduleMonthNow(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}
function scheduleCategoryName(x){return SCHEDULE_CATEGORIES.find(a=>a[0]===x)?.[1]||x||'班表';}
async function openScheduleModule(action,label){
  const titleMap={'schedule-month':'📅 月班表','schedule-staff':'📋 人員班表','schedule-community':'🏢 社區班表','schedule-swap':'🔄 換班紀錄','schedule-leave':'📝 請假／代班','schedule-overtime':'➕ 加班'};
  try{
    scheduleCache=await api('/api/company/schedule/staff');
    const box=document.getElementById('companyWorkspace');
    if(!box) throw new Error('找不到右側工作頁面。');
    document.querySelectorAll('[id^="tab-"]').forEach(el=>el.style.display='none');
    box.style.display='block';
    box.classList.add('schedule-workpage');
    box.innerHTML=`<div class="schedule-page-heading"><div><h2>${titleMap[action]||'📅 班表'}</h2><p>班表設定與紀錄都在此工作頁操作，不會跳出卡片視窗。</p></div><div class="schedule-page-nav">${Object.entries(titleMap).map(([key,name])=>`<button type="button" class="secondary" data-schedule-nav="${key}" ${key===action?'disabled':''}>${name}</button>`).join('')}</div></div><div id="scheduleModuleBody"><div class="profile-loading">班表資料載入中…</div></div>`;
    box.querySelectorAll('[data-schedule-nav]').forEach(b=>b.addEventListener('click',()=>openScheduleModule(b.dataset.scheduleNav,titleMap[b.dataset.scheduleNav])));
    if(action==='schedule-staff') renderScheduleStaff(box);
    else if(action==='schedule-community') renderScheduleCommunity(box);
    else if(action==='schedule-swap') await renderScheduleSwaps(box);
    else if(action==='schedule-leave'){const body=box.querySelector('#scheduleModuleBody');if(window.LeaveModule&&window.CoverModule)await window.LeaveModule.render(body,{base:'/api/company/my',side:'company',label:'請假／代班',tab:'cover',withCover:true,embedded:true});else await renderScheduleRequests(box);}
    else if(action==='schedule-overtime'){const body=box.querySelector('#scheduleModuleBody');if(window.CoverModule)await window.CoverModule.renderOvertime(body,{base:'/api/company/my',side:'company',label:'加班',tab:'all'});else await renderScheduleOvertime(box);}
    else if(window.SmartSchedule&&window.__planModules?.smart_schedule!==false) await window.SmartSchedule.render(box.querySelector('#scheduleModuleBody'));
    else await renderScheduleMonth(box);
  }catch(e){const box=document.getElementById('companyWorkspace');if(box){box.style.display='block';box.innerHTML=`<div class="msg error">${escapeHtml(e.message||'班表模組載入失敗')}</div>`;}else alert(e.message||'班表模組載入失敗');}
}
function scheduleWorkRoot(){return document.getElementById('companyWorkspace');}
function renderScheduleSubpage(title,content){const box=scheduleWorkRoot();if(!box)return null;box.innerHTML=`<div class="schedule-page-heading"><div><h2>${title}</h2><p>班表設定工作頁</p></div><button type="button" class="secondary" id="scheduleBackBtn">← 返回班表列表</button></div><div id="scheduleModuleBody">${content}</div>`;box.querySelector('#scheduleBackBtn')?.addEventListener('click',()=>openScheduleModule('schedule-staff','人員班表'));return box;}
function scheduleToolbar(selected='security',month=scheduleMonthNow(),communityId=''){
  return `<div class="schedule-toolbar">
    <div><label>排班類型</label><select id="scheduleCategory">${SCHEDULE_CATEGORIES.map(([v,n])=>`<option value="${v}" ${v===selected?'selected':''}>${n}</option>`).join('')}</select></div>
    <div><label>月份</label><input id="scheduleMonth" type="month" value="${escapeAttr(month)}"></div>
    <div><label>社區</label><select id="scheduleCommunity"><option value="">全部社區</option>${scheduleCache.communities.map(c=>`<option value="${c.id}" ${String(c.id)===String(communityId)?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div>
    <button id="scheduleGenerateBtn">🤖 智慧排班</button>
  </div>`;
}
async function renderScheduleMonth(box){
  const body=box.querySelector('#scheduleModuleBody');body.innerHTML=`${scheduleToolbar()}<div class="schedule-rule-note">三套規則分開運作：行政依案場合約；保全依日／夜班、月休與指定休；機動依支援社區與休假規則。行政選擇「見紅休」時，依台灣政府行事曆所有紅字日期（含週末、國定假日及補假）安排休假，紅字天數可超過設定的每月休假天數；系統另會檢查連續工作天數與休假衝突。</div><div id="scheduleMonthGrid"><div class="profile-loading">讀取班表中…</div></div>`;
  const load=async()=>{const cat=body.querySelector('#scheduleCategory').value,month=body.querySelector('#scheduleMonth').value,cid=body.querySelector('#scheduleCommunity').value;const d=await api(`/api/company/schedule/month?month=${encodeURIComponent(month)}&category=${encodeURIComponent(cat)}${cid?`&community_id=${encodeURIComponent(cid)}`:''}`);renderScheduleGrid(body.querySelector('#scheduleMonthGrid'),d);};
  body.querySelector('#scheduleCategory').addEventListener('change',load);body.querySelector('#scheduleMonth').addEventListener('change',load);body.querySelector('#scheduleCommunity').addEventListener('change',load);
  body.querySelector('#scheduleGenerateBtn').addEventListener('click',async()=>{const btn=body.querySelector('#scheduleGenerateBtn');btn.disabled=true;try{const cat=body.querySelector('#scheduleCategory').value,month=body.querySelector('#scheduleMonth').value,cid=body.querySelector('#scheduleCommunity').value;const d=await api('/api/company/schedule/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({month,category:cat,community_id:cid||null})});alert(`智慧排班完成：建立／更新 ${d.created||0} 筆。${d.problems?.length?`\n另有 ${d.problems.length} 個規則提醒。`:''}`);await load();}catch(e){alert(e.message)}finally{btn.disabled=false;}});
  await load();
}
function renderScheduleGrid(el,d){
  const days=Array.from({length:new Date(Number(d.month.slice(0,4)),Number(d.month.slice(5,7)),0).getDate()},(_,i)=>i+1);const byStaff={};for(const r of d.entries||[])(byStaff[r.staff_id]??=[]).push(r);const staffIds=[...new Set((d.entries||[]).map(r=>r.staff_id))];
  if(!staffIds.length){el.innerHTML='<div class="empty">目前尚未建立這個類別的班表。可以先設定人員班表身分，再按「🤖 智慧排班」。</div>';return;}
  el.innerHTML=`<div class="table-wrap schedule-grid-wrap"><table class="schedule-grid"><thead><tr><th>人員</th>${days.map(i=>`<th>${i}</th>`).join('')}</tr></thead><tbody>${staffIds.map(id=>{const rows=byStaff[id]||[];const first=rows[0]||{};const map=new Map(rows.map(r=>[Number(r.work_date.slice(-2)),r]));return `<tr><th>${escapeHtml(first.staff_name||'')}</th>${days.map(day=>{const r=map.get(day);const code=r?.shift_code||'';const cls=code==='off'?'off':code==='leave'?'leave':code==='night'?'night':code?'work':'';return `<td class="${cls}" title="${escapeAttr(r?.community_name||'')}">${code==='off'?'休':code==='leave'?'假':code==='night'?'夜':'班'}</td>`}).join('')}</tr>`}).join('')}</tbody></table></div>${d.problems?.length?`<div class="schedule-alerts">${d.problems.map(x=>`<div>⚠️ ${escapeHtml(x.message)}｜${escapeHtml(x.date||'')}</div>`).join('')}</div>`:''}`;
}
function renderScheduleStaff(box,state0){
  const body=box.querySelector('#scheduleModuleBody');const all=scheduleCache.staff||[];const deps=scheduleCache.departments||[];
  const st=state0||renderScheduleStaff._s||(renderScheduleStaff._s={dept:'',q:''});
  const deptOf=u=>u.org?.dept||'';const commOf=u=>(u.site_assignments||[]).map(a=>a.community_name).filter(Boolean);
  const ruleText=u=>{const r=u.rule;if(!r)return '—';if(r.mode==='red_holiday'||r.role==='office')return `見紅休<small>本月 ${r.rest_days} 天（依行事曆）</small>`;if(r.mode==='rotation')return `輪排休<small>本月 ${r.rest_days} 天（依行事曆輪流）</small>`;return `${r.role==='admin'?'固定月休':'排休'}<small>每月 ${r.rest_days} 天${r.self_select_days?`・可自選 ${r.self_select_days} 天`:''}</small>`;};
  const q=st.q.trim().toLowerCase();
  const rows=all.filter(u=>(!st.dept||(st.dept==='_none'?!deptOf(u):deptOf(u)===st.dept))&&(!q||`${u.name} ${u.employee_id} ${commOf(u).join(' ')} ${u.org?.position||''}`.toLowerCase().includes(q)));
  const count=d=>all.filter(u=>d==='_none'?!deptOf(u):deptOf(u)===d).length;
  body.innerHTML=`<div class="schedule-rule-note">每個人的休假制度依職位與社區合約自動判斷：見紅休、輪排休依政府行事曆計算天數；固定月休與保全依設定的天數。點「設定」可以調整個人的班表身分與支援社區。</div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:0 0 12px"><div style="display:flex;gap:6px;flex-wrap:wrap">${[['','全部',all.length],...deps.map(d=>[d.id,d.name,count(d.id)]),...(count('_none')?[['_none','未設定職位',count('_none')]]:[])].map(([v,n,c])=>`<button type="button" class="${st.dept===v?'':'secondary'}" data-sdept="${escapeAttr(v)}" style="padding:6px 12px;min-height:0;margin:0;border-radius:999px">${escapeHtml(n)} ${c}</button>`).join('')}</div><input id="schedStaffQ" placeholder="搜尋姓名、員編或社區" value="${escapeAttr(st.q)}" style="margin:0 0 0 auto;max-width:260px"></div>
    <div class="table-wrap"><table><thead><tr><th>員編</th><th>姓名</th><th>職位</th><th>社區</th><th>班別</th><th>休假制度</th><th>操作</th></tr></thead><tbody>${rows.map(u=>{const p=u.schedule_profile||{};return `<tr><td>${escapeHtml(u.employee_id)}</td><td><strong>${escapeHtml(u.name)}</strong></td><td>${escapeHtml(u.org?.position||u.position||'—')}${u.org?.dept_name?`<br><small class="muted">${escapeHtml(u.org.dept_name)}</small>`:''}</td><td>${escapeHtml(commOf(u).join('、')||'—')}</td><td>${p.default_shift==='night'?'夜班':p.default_shift==='day'?'日班':u.org?.shift==='night'?'夜班':u.org?.shift==='day'?'日班':'—'}</td><td class="sched-rule-cell">${ruleText(u)}</td><td><button class="secondary" onclick="openScheduleStaffEditor(${u.id})">設定</button></td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">找不到符合的人員。</td></tr>'}</tbody></table></div>
    <style>.sched-rule-cell small{display:block;color:#7A5F58;font-size:.78rem}</style>`;
  body.querySelectorAll('[data-sdept]').forEach(b=>b.addEventListener('click',()=>{st.dept=b.dataset.sdept;renderScheduleStaff(box,st);}));
  const qi=body.querySelector('#schedStaffQ');qi.addEventListener('input',()=>{st.q=qi.value;clearTimeout(st.t);st.t=setTimeout(()=>{renderScheduleStaff(box,st);const n=box.querySelector('#schedStaffQ');n.focus();n.setSelectionRange(n.value.length,n.value.length);},250);});
}
function openScheduleStaffEditor(id){
  const u=scheduleCache.staff.find(x=>Number(x.id)===Number(id));if(!u)return;const p=u.schedule_profile||{};const cats=SCHEDULE_CATEGORIES.map(([v,n])=>`<option value="${v}" ${p.schedule_role===v?'selected':''}>${n}</option>`).join('');const communityHtml=scheduleCache.communities.map(c=>`<label class="check-row"><input type="checkbox" data-schedule-cid="${c.id}" ${(p.community_ids||[]).map(Number).includes(Number(c.id))?'checked':''}> ${escapeHtml(c.name)}</label>`).join('');
  const box=renderScheduleSubpage(`📅 ${escapeHtml(u.name)}｜班表設定`,`<div class="editor-grid"><div><label>班表身分</label><select id="scheduleRole">${cats}</select></div><div><label>固定班別</label><select id="scheduleShift"><option value="" ${!p.default_shift?'selected':''}>不指定</option><option value="day" ${p.default_shift==='day'?'selected':''}>日班</option><option value="night" ${p.default_shift==='night'?'selected':''}>夜班</option></select></div><div><label>每月休假天數</label><input id="scheduleRestDays" type="number" min="0" max="31" value="${Number(p.rest_days??6)}"></div><div><label>人員自選休假天數</label><input id="scheduleSelfDays" type="number" min="0" max="31" value="${Number(p.self_select_days??2)}"></div></div><div class="panel-lite"><strong>🏠 支援／服務社區</strong><p class="hint">機動可複選多個社區；系統會用這些社區計算支援路線與休假衝突。</p><div class="check-list">${communityHtml||'<div class="empty">尚未建立社區。</div>'}</div></div><div><label>備註</label><textarea id="scheduleProfileNotes">${escapeHtml(p.notes||'')}</textarea></div><div class="modal-actions"><button class="secondary" type="button" id="scheduleCancelEdit">取消</button><button type="button" onclick="saveScheduleStaff(${id},this)">儲存</button></div>`);
  box?.querySelector('#scheduleCancelEdit')?.addEventListener('click',()=>openScheduleModule('schedule-staff','人員班表'));
}
async function saveScheduleStaff(id,btn){const box=btn.closest('.modal')||scheduleWorkRoot();try{await api(`/api/company/schedule/staff/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({schedule_role:box.querySelector('#scheduleRole').value,default_shift:box.querySelector('#scheduleShift').value,rest_days:Number(box.querySelector('#scheduleRestDays').value),self_select_days:Number(box.querySelector('#scheduleSelfDays').value),community_ids:[...box.querySelectorAll('input[data-schedule-cid]:checked')].map(x=>Number(x.dataset.scheduleCid)),notes:box.querySelector('#scheduleProfileNotes').value})});scheduleCache=await api('/api/company/schedule/staff');alert('班表人員設定已儲存。');openScheduleModule('schedule-staff','人員班表')}catch(e){alert(e.message)}}
function renderScheduleCommunity(box){
  const body=box.querySelector('#scheduleModuleBody');body.innerHTML=`<div class="schedule-rule-note">行政、保全、機動是三套獨立規則。每個社區可以有自己的合約／勤務規則，不會把行政規則套到保全或機動。</div><div class="table-wrap"><table><thead><tr><th>社區</th><th>行政規則</th><th>保全規則</th><th>機動規則</th><th>操作</th></tr></thead><tbody>${scheduleCache.communities.map(c=>`<tr><td><strong>${escapeHtml(c.name)}</strong></td><td>依合約</td><td>日／夜班、月休</td><td>支援／休假</td><td><button class="secondary" onclick="openScheduleRuleEditor(${c.id})">設定規則</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">目前沒有啟用社區。</td></tr>'}</tbody></table></div>`;
}
async function openScheduleRuleEditor(cid){
  const community=scheduleCache.communities.find(c=>Number(c.id)===Number(cid));const configs={};for(const cat of ['admin','security','mobile'])configs[cat]=(await api(`/api/company/schedule/rules?community_id=${cid}&category=${cat}`)).config||{};
  const box=renderScheduleSubpage(`🏢 ${escapeHtml(community?.name||'社區')}｜班表規則`,`<div class="schedule-rule-tabs"><button type="button" class="schedule-tab-admin" data-rule-tab="admin">🏢 行政</button><button type="button" class="schedule-tab-security" data-rule-tab="security">🛡️ 保全</button><button type="button" class="schedule-tab-mobile" data-rule-tab="mobile">🚗 機動</button></div><div id="scheduleRuleFields"></div><div class="modal-actions"><button class="secondary" type="button" id="scheduleRuleCancel">← 返回社區班表</button><button type="button" onclick="saveScheduleRules(${cid},this)">儲存目前規則</button></div>`);
  box._scheduleRuleConfigs=configs;box._scheduleRuleCategory='admin';box.querySelector('#scheduleRuleCancel')?.addEventListener('click',()=>openScheduleModule('schedule-community','社區班表'));renderScheduleRuleFields(box);box.querySelectorAll('[data-rule-tab]').forEach(b=>b.addEventListener('click',()=>{box._scheduleRuleCategory=b.dataset.ruleTab;renderScheduleRuleFields(box)}));
}
function renderScheduleRuleFields(box){
  const cat=box._scheduleRuleCategory,c=box._scheduleRuleConfigs[cat]||{},el=box.querySelector('#scheduleRuleFields');
  const inherit=`<label class="schedule-platform-toggle"><input id="usePlatformDefaults" type="checkbox" ${c.use_platform_defaults!==false?'checked':''}> ⚙️ 跟隨系統總後台「平台規則與設定」</label>`;
  if(cat==='security')el.innerHTML=`${inherit}<div class="editor-grid"><div><label>月休天數</label><input id="ruleRest" type="number" min="0" max="31" value="${Number(c.rest_days??6)}"></div><div><label>人員自選指定休</label><input id="ruleSelf" type="number" min="0" max="31" value="${Number(c.self_select_days??2)}"></div><div><label>最多連續工作</label><input id="ruleMax" type="number" min="1" max="31" value="${Number(c.max_consecutive??6)}"></div><div><label>預設班別</label><select id="ruleShift"><option value="day" ${c.shift==='day'?'selected':''}>日班</option><option value="night" ${c.shift==='night'?'selected':''}>夜班</option></select></div></div><p class="hint">平台總後台可以直接調整母規則；勾選跟隨後，本社區會跟著平台規則更新。若有特殊合約，再取消勾選後自行設定。</p>`;
  else if(cat==='mobile')el.innerHTML=`${inherit}<div class="editor-grid"><div><label>預設月休天數</label><input id="ruleRest" type="number" min="0" max="31" value="${Number(c.rest_days??6)}"></div><div><label>機動自選休</label><input id="ruleSelf" type="number" min="0" max="31" value="${Number(c.self_select_days??2)}"></div><div><label>最多連續工作</label><input id="ruleMax" type="number" min="1" max="31" value="${Number(c.max_consecutive??6)}"></div></div><p class="hint">機動可支援多個社區；平台母規則可以統一控制最多連續工作天數與預設休假。</p>`;
  else el.innerHTML=`${inherit}<div class="panel-lite"><strong>經理規則</strong><div class="editor-grid"><div><label>排休方式</label><select id="managerMode"><option value="red_holiday" ${c.manager?.mode==='red_holiday'?'selected':''}>見紅休</option><option value="rotation" ${c.manager?.mode==='rotation'?'selected':''}>輪排休</option><option value="fixed_monthly" ${c.manager?.mode==='fixed_monthly'?'selected':''}>固定月休</option></select></div><div><label>月休天數</label><input id="managerRest" type="number" min="0" max="31" value="${Number(c.manager?.rest_days??8)}"></div></div></div><div class="panel-lite"><strong>秘書規則</strong><div class="editor-grid"><div><label>排休方式</label><select id="secretaryMode"><option value="red_holiday" ${c.secretary?.mode==='red_holiday'?'selected':''}>見紅休</option><option value="rotation" ${c.secretary?.mode==='rotation'?'selected':''}>輪排休</option><option value="fixed_monthly" ${c.secretary?.mode==='fixed_monthly'?'selected':''}>固定月休</option></select></div><div><label>月休天數</label><input id="secretaryRest" type="number" min="0" max="31" value="${Number(c.secretary?.rest_days??8)}"></div></div></div><p class="hint schedule-holiday-note">📅 見紅休：依台灣年度國定假日資料自動固定休假；輪排休：以當年度國定假日作為輪排休假依據，再補足合約月休天數。最長連續工作天數由平台母規則統一控制。</p><p class="hint">🔒 行政只套用公司在社區開通時設定的合約規則，不會進入勤務主管的保全視野。</p>`;
  // 見紅休、輪排休的天數依行事曆自動計算，只有固定月休可以設定天數
  if(cat==='admin'){const sync=async()=>{let red=null;try{red=(await api('/api/company/my/schedule/my-rule')).red_count;}catch{}for(const k of ['manager','secretary']){const sel=el.querySelector('#'+k+'Mode'),inp=el.querySelector('#'+k+'Rest');if(!sel||!inp)continue;const fixed=sel.value==='fixed_monthly';inp.disabled=!fixed;inp.style.opacity=fixed?'1':'.55';let note=inp.parentNode.querySelector('.rest-note');if(!note){note=document.createElement('small');note.className='rest-note';note.style.cssText='display:block;color:#7A5F58;margin-top:4px';inp.parentNode.appendChild(note);}note.textContent=fixed?'固定月休：每月休這個天數，可以開放自選。':`${sel.value==='red_holiday'?'見紅休':'輪排休'}：依政府行事曆自動計算${red!==null?`（本月 ${red} 天）`:''}，不用設定。`;}};el.querySelectorAll('#managerMode,#secretaryMode').forEach(x=>x.addEventListener('change',sync));sync();}
}

async function saveScheduleRules(cid,btn){const box=btn.closest('.modal')||scheduleWorkRoot(),cat=box._scheduleRuleCategory,c=box._scheduleRuleConfigs[cat]||{};try{let cfg;if(cat==='security')cfg={...c,rest_days:Number(box.querySelector('#ruleRest').value),self_select_days:Number(box.querySelector('#ruleSelf').value),max_consecutive:Number(box.querySelector('#ruleMax').value),shift:box.querySelector('#ruleShift').value,use_platform_defaults:!!box.querySelector('#usePlatformDefaults')?.checked};else if(cat==='mobile')cfg={...c,rest_days:Number(box.querySelector('#ruleRest').value),self_select_days:Number(box.querySelector('#ruleSelf').value),max_consecutive:Number(box.querySelector('#ruleMax').value),use_platform_defaults:!!box.querySelector('#usePlatformDefaults')?.checked};else cfg={...c,manager:{...(c.manager||{}),mode:box.querySelector('#managerMode').value,rest_days:Number(box.querySelector('#managerRest').value)},secretary:{...(c.secretary||{}),mode:box.querySelector('#secretaryMode').value,rest_days:Number(box.querySelector('#secretaryRest').value)},use_platform_defaults:!!box.querySelector('#usePlatformDefaults')?.checked};await api('/api/company/schedule/rules',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({community_id:cid,category:cat,config:cfg})});box._scheduleRuleConfigs[cat]=cfg;alert(cfg.use_platform_defaults?'已儲存：此社區會跟隨平台母規則。':'已儲存：此社區使用自訂班表規則。')}catch(e){alert(e.message)}}

async function renderScheduleSwaps(box){const d=await api('/api/company/schedule/swaps');const body=box.querySelector('#scheduleModuleBody');body.innerHTML=`<div class="schedule-rule-note">所有換班都留下紀錄，不直接覆蓋原班表。</div><div class="editor-grid"><div><label>日期</label><input id="swapDate" type="date"></div><div><label>社區</label><select id="swapCommunity"><option value="">不指定</option>${scheduleCache.communities.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')}</select></div><div><label>原值班人員</label><select id="swapFrom">${scheduleCache.staff.map(u=>`<option value="${u.id}">${escapeHtml(u.name)}</option>`).join('')}</select></div><div><label>代班人員</label><select id="swapTo">${scheduleCache.staff.map(u=>`<option value="${u.id}">${escapeHtml(u.name)}</option>`).join('')}</select></div></div><label>原因</label><textarea id="swapReason"></textarea><div class="modal-actions"><button onclick="saveScheduleSwap(this)">建立換班紀錄</button></div><div id="scheduleSwapList">${renderScheduleSwapRows(d.rows||[])}</div>`;}
function renderScheduleSwapRows(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>日期</th><th>社區</th><th>原人員</th><th>代班</th><th>原因</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHtml(r.work_date)}</td><td>${escapeHtml(r.community_name||'—')}</td><td>${escapeHtml(r.from_name)}</td><td>${escapeHtml(r.to_name)}</td><td>${escapeHtml(r.reason||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">目前沒有換班紀錄。</div>';}
async function saveScheduleSwap(btn){const box=btn.closest('.modal')||scheduleWorkRoot();try{await api('/api/company/schedule/swaps',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({work_date:box.querySelector('#swapDate').value,community_id:box.querySelector('#swapCommunity').value||null,from_staff_id:box.querySelector('#swapFrom').value,to_staff_id:box.querySelector('#swapTo').value,reason:box.querySelector('#swapReason').value})});alert('換班紀錄已建立。');await openScheduleModule('schedule-swap','換班紀錄');}catch(e){alert(e.message)}}
async function renderScheduleRequests(box){const d=await api('/api/company/schedule/requests');const body=box.querySelector('#scheduleModuleBody');body.innerHTML=`<div class="schedule-rule-note">請假與代班不刪除原始排班；系統會保留申請／處理紀錄。</div><div class="editor-grid"><div><label>人員</label><select id="reqStaff">${scheduleCache.staff.map(u=>`<option value="${u.id}">${escapeHtml(u.name)}</option>`).join('')}</select></div><div><label>日期</label><input id="reqDate" type="date"></div><div><label>類型</label><select id="reqType"><option value="leave">請假</option><option value="cover">代班</option></select></div><div><label>代班人員（可選）</label><select id="reqTarget"><option value="">不指定</option>${scheduleCache.staff.map(u=>`<option value="${u.id}">${escapeHtml(u.name)}</option>`).join('')}</select></div></div><label>原因</label><textarea id="reqReason"></textarea><div class="modal-actions"><button onclick="saveScheduleRequest(this)">建立紀錄</button></div><div id="scheduleReqList">${renderScheduleRequestRows(d.rows||[])}</div>`;}
function renderScheduleRequestRows(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>日期</th><th>人員</th><th>類型</th><th>代班</th><th>原因</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHtml(r.work_date)}</td><td>${escapeHtml(r.staff_name)}</td><td>${r.request_type==='cover'?'代班':'請假'}</td><td>${escapeHtml(r.target_staff_name||'—')}</td><td>${escapeHtml(r.reason||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">目前沒有請假／代班紀錄。</div>';}
async function saveScheduleRequest(btn){const box=btn.closest('.modal')||scheduleWorkRoot();try{await api('/api/company/schedule/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({staff_id:box.querySelector('#reqStaff').value,work_date:box.querySelector('#reqDate').value,request_type:box.querySelector('#reqType').value,target_staff_id:box.querySelector('#reqTarget').value||null,reason:box.querySelector('#reqReason').value})});alert('紀錄已建立。');await openScheduleModule('schedule-leave','請假／代班');}catch(e){alert(e.message)}}
async function renderScheduleOvertime(box){const d=await api('/api/company/schedule/overtime');const body=box.querySelector('#scheduleModuleBody');body.innerHTML=`<div class="schedule-rule-note">加班獨立於基本班表。機動可支援多個社區，也可以另外登錄加班，不會被固定 23／24 天限制綁死。</div><div class="editor-grid"><div><label>人員</label><select id="otStaff">${scheduleCache.staff.map(u=>`<option value="${u.id}">${escapeHtml(u.name)}</option>`).join('')}</select></div><div><label>日期</label><input id="otDate" type="date"></div><div><label>社區</label><select id="otCommunity"><option value="">不指定</option>${scheduleCache.communities.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')}</select></div><div><label>加班時數</label><input id="otHours" type="number" min="0.5" step="0.5" value="1"></div></div><label>原因／備註</label><textarea id="otReason"></textarea><div class="modal-actions"><button onclick="saveScheduleOvertime(this)">＋ 登錄加班</button></div><div id="scheduleOtList">${renderScheduleOvertimeRows(d.rows||[])}</div>`;}
function renderScheduleOvertimeRows(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>日期</th><th>人員</th><th>社區</th><th>時數</th><th>類別</th><th>原因</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHtml(r.work_date)}</td><td>${escapeHtml(r.staff_name)}</td><td>${escapeHtml(r.community_name||'—')}</td><td>${r.hours}</td><td>${escapeHtml(r.category||'')}</td><td>${escapeHtml(r.reason||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">目前沒有加班紀錄。</div>';}
async function saveScheduleOvertime(btn){const box=btn.closest('.modal')||scheduleWorkRoot();try{await api('/api/company/schedule/overtime',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({staff_id:box.querySelector('#otStaff').value,work_date:box.querySelector('#otDate').value,community_id:box.querySelector('#otCommunity').value||null,hours:Number(box.querySelector('#otHours').value),reason:box.querySelector('#otReason').value})});alert('加班紀錄已建立。');await openScheduleModule('schedule-overtime','加班');}catch(e){alert(e.message)}}
window.openScheduleModule=openScheduleModule;window.openScheduleStaffEditor=openScheduleStaffEditor;window.saveScheduleStaff=saveScheduleStaff;window.openScheduleRuleEditor=openScheduleRuleEditor;window.saveScheduleRules=saveScheduleRules;window.saveScheduleSwap=saveScheduleSwap;window.saveScheduleRequest=saveScheduleRequest;window.saveScheduleOvertime=saveScheduleOvertime;

(function(){if(document.getElementById('scheduleRoleColorsV7'))return;const s=document.createElement('style');s.id='scheduleRoleColorsV7';s.textContent=`.schedule-rule-tabs button{font-weight:700;min-width:110px}.schedule-rule-tabs .schedule-tab-admin{color:#512D28;background:#F4EFE7;border-color:#C7B0AB}.schedule-rule-tabs .schedule-tab-security{color:#174f78;background:#e7f1fb;border-color:#9dc5e5}.schedule-rule-tabs .schedule-tab-mobile{color:#7a4b12;background:#fff2d8;border-color:#e4c17d}.schedule-holiday-note{background:#fff8e7;border:1px solid #efd79b;padding:10px 12px;border-radius:9px}`;document.head.appendChild(s)})();

(function(){if(document.getElementById('schedulePlatformRuleV8'))return;const s=document.createElement('style');s.id='schedulePlatformRuleV8';s.textContent=`.schedule-platform-toggle{display:flex;align-items:center;gap:8px;margin:0 0 14px;padding:10px 12px;border:1px solid #D2C4BF;background:#F7F5F1;border-radius:10px;font-weight:700;color:#4F3430}.schedule-platform-toggle input{width:18px;height:18px}`;document.head.appendChild(s)})();

async function downloadPlatformResource(id){window.open(`/api/company/platform-resources/${id}/download`,'_blank')}
async function adoptPlatformResource(id){if(!confirm('要把這份平台公版文件複製到本公司資源嗎？'))return;try{await api(`/api/company/platform-resources/${id}/adopt`,{method:'POST'});await loadAll();alert('已採用這份平台公版文件。')}catch(e){alert(e.message)}}
async function downloadCompanyResource(id){window.open(`/api/company/resources/${id}/download`,'_blank')}
async function deleteCompanyResource(id){if(!confirm('確定刪除本公司的這份資源嗎？平台原始公版不會受影響。'))return;try{await api(`/api/company/resources/${id}`,{method:'DELETE'});await loadAll();alert('已刪除公司資源。')}catch(e){alert(e.message)}}

// 面試電腦：這台電腦設定過公司代碼、且公司已開通面試功能時，登入頁右下角才顯示「面試人員填寫履歷」
(function(){try{const c=localStorage.getItem('interviewCompany');const a=document.getElementById('interviewEntry');if(!c||!a)return;fetch(`/api/interview/${encodeURIComponent(c)}/meta`,{cache:'no-store'}).then(r=>{if(r.ok)a.style.display='';}).catch(()=>{});}catch{}})();
